    id: "return-chasing-behavior-gap", section: "670", title: "Return-Chasing / The Behavior Gap → Buying High, Selling Low", subtitle: "Degrades: realized returns, retirement funding, compounding",
    evidenceTag: "Moderate",
    weakness: { threat: 6, weakLines: ["Financial", "Volitional", "Strategic"], degree: "major contributor", onset: "years", reversibility: "recovers" },
