    id: "ocd-functional-impairment", section: "714", title: "Obsessive-Compulsive Disorder — Functional & Quality-of-Life Loss", subtitle: "Degrades: Volitional drive, Meta-cognitive flexibility, Interpersonal function, Occupational output, Emotional regulation",
    evidenceTag: "Moderate",
    harm: { severity: 4, onset: "years", reversibility: "partial" },
